#!/usr/bin/env bash
# Regenerates src/generated/: the FeeVault creation code the hook's constructor deploys (Solidity's
# `new FeeVault(poolManager)`). CI fails if the committed file is stale.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
code="$(hnc src/FeeVault.huff -b)"
# Publish a complete file atomically; concurrent FFI compilations must never see an empty table.
generated_tmp="$(mktemp src/generated/.FeeVaultCreation.XXXXXX)"
trap 'rm -f "$generated_tmp"' EXIT
cat > "$generated_tmp" <<HUFF
/// @dev Generated by script/huff-codegen.sh from src/FeeVault.huff. Do not edit.
#define table FEE_VAULT_CREATION {
    0x${code}
}
HUFF

chmod 644 "$generated_tmp"
mv "$generated_tmp" src/generated/FeeVaultCreation.huff
